// A reviewer read this and approved it — looks fine line by line.
function makeBuggyAccount(balance) {
  return {
    balance,
    // check-then-act: read balance, decide, then write. The gap is the bug.
    withdraw(amount) {
      const current = this.balance;        // read
      if (current >= amount) {             // check (against the stale read)
        this.balance = current - amount;   // act (writes back the stale read)
        return true;
      }
      return false;
    }
  };
}

// Deterministic interleaving: both ops capture the balance BEFORE either writes.
function runInterleaved(account, amount) {
  const c1 = account.balance;
  const c2 = account.balance;            // second 'thread' reads the same stale value
  let ok1 = false, ok2 = false;
  if (c1 >= amount) { ok1 = true; }
  if (c2 >= amount) { ok2 = true; }
  if (ok1) account.balance = c1 - amount;
  if (ok2) account.balance = c2 - amount; // clobbers, double-spends
  return account.balance;
}

// The test the reviewer should have demanded:
const buggy = makeBuggyAccount(100);
const finalBuggy = runInterleaved(buggy, 100); // two 100-withdrawals on a 100 balance
console.log(finalBuggy < 0 ? 'FAIL buggy: balance went negative -> ' + finalBuggy
                           : 'unexpected: ' + finalBuggy);

// The fix: make read-decide-write atomic (no interleaving window).
function makeFixedAccount(balance) {
  return {
    balance,
    _locked: false,
    withdraw(amount) {
      // serialize: only one withdrawal commits at a time
      if (this._locked) return false;
      this._locked = true;
      let result = false;
      if (this.balance >= amount) { this.balance -= amount; result = true; }
      this._locked = false;
      return result;
    }
  };
}

const fixed = makeFixedAccount(100);
const ok1 = fixed.withdraw(100);
const ok2 = fixed.withdraw(100); // second one must be rejected
console.log(fixed.balance >= 0 && !(ok1 && ok2)
  ? 'PASS fixed: only one withdrawal committed, balance=' + fixed.balance
  : 'FAIL fixed: balance=' + fixed.balance);

